CSS='''<style>:root{--brand:#01dc82;--deep:#033330;--lime:#cfe66a;--red:#b3261e;--amber:#9a6700;--ink:#0f172a;--muted:#475569;--line:#e2e8f0;--bg:#fafaf9;--card:#fff;--serif:Newsreader,Georgia,serif;--sans:"Plus Jakarta Sans",ui-sans-serif,system-ui,sans-serif}*{box-sizing:border-box}body{margin:0;background:var(--bg);color:var(--ink);font-family:var(--sans);line-height:1.55}main{max-width:64rem;margin:auto;padding:3rem 1.5rem}header{display:flex;flex-direction:column;gap:1rem;margin-bottom:2.2rem}.wordmark{display:flex;align-items:center;gap:.6rem;font-weight:700;color:var(--deep)}h1,h2{font-family:var(--serif);color:var(--deep);font-weight:600}h1{font-size:2.25rem;margin:0}h2{font-size:1.35rem;margin:0 0 .5rem}h3{font-size:.72rem;text-transform:uppercase;letter-spacing:.08em;color:var(--muted);margin:1.1rem 0 .35rem}.dek{max-width:54rem;color:var(--muted);font-size:1rem}.card{background:var(--card);border:1px solid var(--line);border-radius:.75rem;padding:1.4rem;margin:1rem 0}.badges{display:flex;flex-wrap:wrap;gap:.45rem;margin:.25rem 0 .8rem}.badge{font-size:.68rem;text-transform:uppercase;letter-spacing:.06em;font-weight:700;padding:.15rem .5rem;border-radius:.35rem;background:#f1f5f9;color:var(--muted)}.good{background:#dcfce7;color:#166534}.warn{background:#fef3c7;color:var(--amber)}.spec{background:#e2e8f0;color:#334155}.facts{font-family:ui-monospace,monospace;font-size:.78rem;color:var(--muted);list-style:none;padding:0;margin:.4rem 0}.facts li{padding:.12rem 0}.diagram{border:1px solid var(--line);border-radius:.5rem;background:#fff;padding:.8rem;margin:1rem 0}.diagram svg{display:block;max-width:100%;height:auto}.label{font-size:11px;text-transform:uppercase;letter-spacing:.08em;fill:var(--muted)}.wins{margin:.5rem 0 0;padding-left:1.1rem}.wins li{margin:.15rem 0}.callout{border-left:3px solid var(--amber);background:#fffbeb;color:#713f12;padding:.6rem .9rem;border-radius:.25rem;font-size:.88rem}a{color:#087f55}.source{font-size:.85rem;word-break:break-word}.matrix{width:100%;border-collapse:collapse;font-size:.82rem}.matrix th,.matrix td{border-bottom:1px solid var(--line);padding:.55rem;text-align:left;vertical-align:top}.matrix th{color:var(--deep);font-size:.72rem;text-transform:uppercase;letter-spacing:.06em}.top{border-left:4px solid var(--brand)}.small{font-size:.86rem;color:var(--muted)}.grid{display:grid;grid-template-columns:repeat(auto-fit,minmax(220px,1fr));gap:1rem}.grid .card{margin:0}ul{padding-left:1.1rem}</style>'''
