ledger={'date':'2026-08-16','generated_at':datetime.datetime.now(datetime.timezone.utc).isoformat(),'editorial_thesis':'The useful frontier is operational: durable agent lifecycles, explicit security controls, portable execution, and identity-aware collaboration outperform another generic model roundup.','topic_groups':[]}
for slug,(title,dek,labels,items,rows,actions) in lanes.items():
 (OUT/f'daily-ingest-{slug}-{DATE}.html').write_text(lane(slug,title,dek,labels,items,rows,actions),encoding='utf-8')
 ledger['topic_groups'].append({'slug':slug,'title':title,'selection_rationale':dek,'sources':[{'title':x[0],'url':x[2],'source_type':'blog' if 'blog' in x[2] else 'release','published_or_updated':'2026-08-13' if 'linear' in x[2] else '2026-08-11','why_selected':x[3],'usefulness':x[5]} for x in items]})

links=''.join(f'<article class="card"><h2>{t}</h2><p>{d}</p><a href="{slug}.html">Open lane report →</a></article>' for slug,(t,d,*_) in lanes.items())
top='<ol><li>Map one Buildn workflow to an ADLC with checkpoints, traces, and a human gate.</li><li>Run a zero-trust gap assessment across one agent’s identity, tools, memory, and runtime.</li><li>Package one recurring task as a portable plugin contract with plan and rewind semantics.</li></ol>'
source_links=''.join('<li><a href="{0}">{1}</a></li>'.format(s['url'],s['title']) for g in ledger['topic_groups'] for s in g['sources'])
overview_body='''<section><article class="card top"><h2>Executive readout</h2><p>{thesis}</p><div class="diagram"><svg viewBox="0 0 680 150" role="img" aria-label="Four selected lanes"><rect x="20" y="30" width="140" height="55" rx="8" fill="#dcfce7"/><text x="90" y="63" text-anchor="middle" class="label">lifecycle</text><rect x="185" y="30" width="140" height="55" rx="8" fill="#fef3c7"/><text x="255" y="63" text-anchor="middle" class="label">security</text><rect x="350" y="30" width="140" height="55" rx="8" fill="#e2e8f0"/><text x="420" y="63" text-anchor="middle" class="label">portability</text><rect x="515" y="30" width="140" height="55" rx="8" fill="#dcfce7"/><text x="585" y="63" text-anchor="middle" class="label">identity</text><path d="M90 105 H585" stroke="#01dc82" stroke-width="3" stroke-dasharray="5 5"/><text x="340" y="135" text-anchor="middle" class="label">operational controls are the connective tissue</text></svg></div></article><h2>Selected lanes</h2><div class="grid">{links}</div><article class="card"><h2>All-lanes top three</h2>{top}</article><article class="card"><h2>Selection rationale</h2><ul><li>Rotates away from yesterday’s platform-release and security-report emphasis toward lifecycle design and collaboration.</li><li>Prioritizes primary sources with direct implementation consequences.</li><li>Uses only sources not present in the durable coverage ledger.</li></ul></article><article class="card"><h2>Source trail</h2><ul>{source_links}</ul></article></section>'''.format(thesis=ledger['editorial_thesis'],links=links,top=top,source_links=source_links)
overview=shell('Daily Ingest Dossier — Overview',ledger['editorial_thesis'],overview_body)
(OUT/f'daily-ingest-overview-{DATE}.html').write_text(overview,encoding='utf-8')
(OUT/f'daily-ingest-{DATE}.json').write_text(json.dumps(ledger,indent=2),encoding='utf-8')
